<script setup>
import { WORKFLOW_COPY_RULES } from '../../../../src/shared/workflow-copy-rules.js';
import { computed, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { createIndependentImageNode, createImageReference } from '../../utils/workflow-image-nodes.js';
import WorkflowMaterialReferences from './WorkflowMaterialReferences.vue';
import WorkflowValuePreview from './WorkflowValuePreview.vue';
import WorkflowMaterialInput from './WorkflowMaterialInput.vue';
import { createWorkflowNode, WORKFLOW_TYPES } from '../../../../src/shared/product-workflow.js';
import { isWorkflowInput, workflowDefault } from '../../../../src/shared/product-workflow-inputs.js';
import { workflowTemplateFields, workflowNodeOutputs } from '../../../../src/shared/product-workflow-bindings.js';
const props=defineProps({definition:{type:Object,required:true},category:{type:Object,required:true},mode:{type:String,default:'all'}});
const emit=defineEmits(['upload']);
const fieldKey=ref('title'),selectedId=ref(''),search=ref(''),drag=ref(null);
const fields=computed(()=>workflowTemplateFields(props.category));
const coreGroups=[{label:'商品内容',keys:['title','tags','description','richContent','images']},{label:'价格与包装',keys:['price','weight','length','width','height']}];
const filteredFields=computed(()=>fields.value.filter(f=>f.key.startsWith('attribute_')&&f.label.toLowerCase().includes(search.value.toLowerCase())));
const fieldFor=key=>fields.value.find(f=>f.key===key);
const fieldSummary=key=>props.definition.bindings[key]?.sources.length?props.definition.bindings[key].sources.map(outputLabel).join(' ＋ '):'待配置来源／上架前补齐';
const field=computed(()=>fields.value.find(f=>f.key===fieldKey.value)||fields.value[0]);
const nodes=computed(()=>props.definition.nodes.filter(n=>n.type!=='listing'));
const selected=computed(()=>nodes.value.find(n=>n.id===selectedId.value));
watch(selected,node=>{if(node?.type==='field'&&!node.inputFormat&&Object.entries(props.definition.bindings).some(([key,b])=>['price','weight','length','width','height'].includes(key)&&b.sources.some(ref=>ref.nodeId===node.id)))node.inputFormat='number';});
const showFields=computed(()=>['all','fields'].includes(props.mode));
const visibleNodes=computed(()=>{const list=nodes.value.filter(n=>props.mode==='images'?n.type==='image':props.mode==='text'?n.type==='copy':true);if(props.mode!=='fields')return list;const rank=node=>props.definition.bindings[fieldKey.value]?.sources.some(s=>s.nodeId===node.id)?0:['image','copy'].includes(node.type)?1:2;return [...list].sort((a,b)=>rank(a)-rank(b));});
watch([()=>props.mode,()=>props.definition.nodes],(current,previous=[])=>{if(showFields.value){if(current[0]!==previous[0])selectField(fieldKey.value);return;}if(!visibleNodes.value.some(n=>n.id===selectedId.value))selectedId.value=visibleNodes.value[0]?.id||'';},{immediate:true});
const referenceEditors=computed(()=>selected.value?.type==='image'&&selected.value.imageMode!=='material'?props.definition.nodes.filter(n=>n.type==='images'&&n.valueSource==='engineer'&&n.referenceRole==='style'&&(selected.value.role==='main'||n.id!=='style')&&selected.value.inputs.includes(n.id)).map(node=>({node,indices:selected.value.referenceSlots?.[node.id]?.length?selected.value.referenceSlots[node.id]:node.slots.map((_,i)=>i)})):[]);
function referenceNode(entry){return {...entry.node,count:entry.indices.length,slots:entry.indices.map(i=>entry.node.slots[i])};}
function updateReference(entry,values){entry.node.defaultValue||=Array(entry.node.count).fill('');entry.indices.forEach((slot,i)=>{entry.node.defaultValue[slot]=values[i]||'';});}
function addImageReference(){const node=selected.value;if(node?.type!=='image')return;const reference=createImageReference(node);insert(reference);node.inputs.push(reference.id);selectedId.value=node.id;}
function removeImageReference(id){const node=selected.value;node.inputs=node.inputs.filter(input=>input!==id);if(node.referenceSlots)delete node.referenceSlots[id];}
const outputs=computed(()=>nodes.value.flatMap(workflowNodeOutputs));
const binding=computed(()=>props.definition.bindings[field.value.key]||{sources:[]});
const earlier=computed(()=>props.definition.nodes.slice(0,props.definition.nodes.findIndex(n=>n.id===selectedId.value)).filter(n=>selected.value?.type==='copy'?['field','attribute','copy'].includes(n.type):isWorkflowInput(n)||['image','copy','approval'].includes(n.type)));
const outputKey=o=>`${o.nodeId}:${o.output}`;
const outputLabel=ref=>outputs.value.find(o=>outputKey(o)===outputKey(ref))?.label||'已删除的节点';
const compatible=(output,target=field.value)=>target.kind==='rich'||target.kind==='images'?target.kind==='rich'||output.kind==='image':output.kind==='text';
function selectField(key){fieldKey.value=key;selectedId.value=props.definition.bindings[key]?.sources[0]?.nodeId||'';}
function insert(node){
  const index=isWorkflowInput(node)?props.definition.nodes.findIndex(n=>['image','copy','approval'].includes(n.type)):-1;
  props.definition.nodes.splice(index<0?props.definition.nodes.length:index,0,node);selectedId.value=node.id;
}
const sourceTypes={user:'用户输入',fixed:'预先定义',copy:'AI 文本生成',image:'AI 图片生成'};
const currentSource=computed(()=>selected.value?isWorkflowInput(selected.value)?selected.value.valueSource==='engineer'?'fixed':'user':selected.value.type:'user');
function create(type){
  if(type==='image'){const {node,reference}=createIndependentImageNode(props.definition.nodes);insert(reference);insert(node);if(showFields.value)bind(workflowNodeOutputs(node)[0]);return;}
  const input=['user','fixed'].includes(type),node=createWorkflowNode(input?'field':type);
  node.label=sourceTypes[type];
  if(input)Object.assign(node,{scope:'shared',valueSource:type==='fixed'?'engineer':'user',inputFormat:field.value.kind==='number'?'number':'text',required:false,defaultValue:''});
  if(type==='copy'){node.target='text';node.prompt='根据引用材料与已确认事实生成所需俄语文本，不编造信息。';}
  if(type==='copy')node.inputs=props.definition.nodes.filter(isWorkflowInput).filter(n=>n.valueSource!=='generated'&&n.type!=='images').map(n=>n.id);
  insert(node);if(showFields.value)bind(workflowNodeOutputs(node)[0]);
}
function changeSource(type){
 const old=selected.value;if(!old)return;
 if(['user','fixed'].includes(type)&&isWorkflowInput(old)){old.valueSource=type==='fixed'?'engineer':'user';if(type==='user')old.defaultValue=old.type==='images'?Array(old.count).fill(''):'';old.required=false;return;}
 const input=['user','fixed'].includes(type),node=createWorkflowNode(input?'field':type,old.id);if(type==='copy')node.target='text';
 Object.assign(node,{label:old.label,...(input?{valueSource:type==='fixed'?'engineer':'user',scope:old.scope||'shared',inputFormat:'text',required:false,defaultValue:''}:{inputs:old.inputs.filter(id=>earlier.value.some(n=>n.id===id))})});
 props.definition.nodes.splice(props.definition.nodes.findIndex(n=>n.id===old.id),1,node);rebind(node);
}
function rebind(node){const output=workflowNodeOutputs(node)[0];for(const [key,binding] of Object.entries(props.definition.bindings)){const target=fieldFor(key);binding.sources=binding.sources.flatMap(source=>{if(source.nodeId!==node.id)return [source];if(!output||!compatible(output,target)){ElMessage.warning(`“${target.label}”与新来源格式不匹配，请重新绑定`);return [];}return [{nodeId:node.id,output:output.output}];});}}

function manual(){
  const source=binding.value.sources.map(r=>props.definition.nodes.find(n=>n.id===r.nodeId)).find(n=>isWorkflowInput(n)&&n.valueSource!=='generated');
  if(source){selectedId.value=source.id;return;}
  const node=field.value.attribute?JSON.parse(JSON.stringify(field.value.attribute)):createWorkflowNode(field.value.kind==='images'?'images':'field');
  if(field.value.attribute)node.id=createWorkflowNode('field').id;
  Object.assign(node,{label:field.value.label,valueSource:'user',scope:'shared',required:false,inputFormat:field.value.kind==='number'?'number':'text'});
  if(node.type==='images')Object.assign(node,{valueSource:'user',defaultValue:['']});
  insert(node);bind(workflowNodeOutputs(node)[0]);
}
function bind(output,target=field.value){
  if(!output)return;
  if(!compatible(output,target))return ElMessage.warning(`“${target.label}”需要${target.kind==='images'?'图片':'文本'}来源；富文本可同时组合图片和文本`);
  const current=props.definition.bindings[target.key] ||= {sources:[]};
  if(!current.sources.some(o=>outputKey(o)===outputKey(output)))current.sources.push({nodeId:output.nodeId,output:output.output});
}
function removeBinding(index){binding.value.sources.splice(index,1);}
function moveBinding(index,direction){const next=index+direction;if(next<0||next>=binding.value.sources.length)return;const [item]=binding.value.sources.splice(index,1);binding.value.sources.splice(next,0,item);}
function start(event,payload){drag.value=payload;event.dataTransfer.setData('text/plain',JSON.stringify(payload));event.dataTransfer.effectAllowed='copy';}
function drop(event,target=field.value){event.preventDefault();const payload=drag.value;drag.value=null;if(payload?.type==='output')bind(payload.output,target);else if(payload?.type==='node')create(payload.nodeType);}
function dropInput(event){event.preventDefault();const payload=drag.value;drag.value=null;if(payload?.type!=='output'||!selected.value)return;const id=payload.output.nodeId;if(!earlier.value.some(n=>n.id===id))return ElMessage.warning('只能引用前面的节点，避免循环依赖');if(!selected.value.inputs.includes(id))selected.value.inputs.push(id);}
async function removeNode(){try{await ElMessageBox.confirm('删除后会移除其他字段和节点对它的引用，保存流程后生效。','删除节点',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});}catch{return;}const id=selected.value.id;for(const node of props.definition.nodes)node.inputs=node.inputs.filter(n=>n!==id);for(const value of Object.values(props.definition.bindings))value.sources=value.sources.filter(r=>r.nodeId!==id);props.definition.nodes=props.definition.nodes.filter(n=>n.id!==id);selectedId.value='';}
function duplicate(){const node=JSON.parse(JSON.stringify(selected.value));node.id=createWorkflowNode(node.type).id;node.label+=' 副本';props.definition.nodes.splice(props.definition.nodes.findIndex(n=>n.id===selected.value.id)+1,0,node);selectedId.value=node.id;}
function changeFormat(format){const old=selected.value;if(old.type==='attribute'&&old.dictionaryId)return;const node=format==='images'?{...createWorkflowNode('images',old.id),label:old.label,scope:old.scope,valueSource:old.valueSource,required:old.required,inputFormat:'images',defaultValue:['']}:{...createWorkflowNode('field',old.id),label:old.label,scope:old.scope,valueSource:old.valueSource,required:old.required,inputFormat:format,defaultValue:''};props.definition.nodes.splice(props.definition.nodes.findIndex(n=>n.id===old.id),1,node);rebind(node);}

function slotsChanged(){const node=selected.value;node.slots=Array.from({length:node.count},(_,i)=>node.slots[i]||`第 ${i+1} 张图片用途`);node.defaultValue=Array.from({length:node.count},(_,i)=>node.defaultValue?.[i]||'');}
</script>
<template>
  <div class="binding-builder" :class="{compact:mode!=='all','compact-fields':mode==='fields'}">
    <section v-if="showFields" class="builder-panel template-panel">
      <div class="section-head"><div><h3>上架模板字段</h3><p>按草稿箱的商品内容、售价与包装字段横向配置。常用字段始终显示；先保存模板，上架前补齐内容。</p></div><el-tag effect="plain">点击字段编辑，或拖入节点输出</el-tag></div>
      <div v-for="group in coreGroups" :key="group.label" class="field-group"><h4>{{ group.label }}</h4><div class="field-grid"><button v-for="key in group.keys" :key="key" class="template-field" :class="{active:fieldKey===key,unconfigured:!definition.bindings[key]?.sources.length}" @click="selectField(key)" @dragover.prevent @drop.stop="drop($event,fieldFor(key))"><strong>{{ fieldFor(key).label }}</strong><span>{{ fieldSummary(key) }}</span><small>{{ definition.bindings[key]?.sources.length?'已配置来源':'待配置' }}</small></button></div></div>
      <el-collapse class="extra-fields"><el-collapse-item :title="`其他类目属性（${fields.filter(f=>f.key.startsWith('attribute_')).length}）`" name="attributes"><el-input v-model="search" placeholder="搜索其他类目属性" clearable/><div class="field-grid"><button v-for="item in filteredFields" :key="item.key" class="template-field" :class="{active:fieldKey===item.key}" @click="selectField(item.key)" @dragover.prevent @drop.stop="drop($event,item)"><strong>{{ item.label }}</strong><small v-if="item.attribute?.platformRequired">平台上架必填</small><span>{{ fieldSummary(item.key) }}</span></button></div><el-empty v-if="!filteredFields.length" description="没有匹配的类目属性" :image-size="45"/></el-collapse-item></el-collapse>
    </section>
    <aside v-if="showFields" class="builder-panel sources-panel">
      <h3>添加来源节点</h3><p>四种来源，按用途直接选择</p>
      <button v-for="(label,type) in sourceTypes" :key="type" class="source-type" draggable="true" @dragstart="start($event,{type:'node',nodeType:type})" @click="create(type)">{{ label }} ＋</button>

    </aside>
    <main class="builder-panel edit-panel" @dragover.prevent @drop="drop($event)">
      <template v-if="showFields"><div class="section-head"><div><h3>{{ field.label }}</h3><p>将右侧节点输出拖入这里，或直接选择；一个输出可多次复用</p></div><el-button @click="manual">添加用户输入</el-button></div>
      <div class="binding-drop" @dragover.prevent @drop.stop="drop($event)">
        <p v-if="!binding.sources.length">拖入已有输出作为此字段的内容</p>
        <div v-for="(source,index) in binding.sources" :key="outputKey(source)" class="bound-source"><span>{{ index+1 }}. {{ outputLabel(source) }}</span><el-button text @click="selectedId=source.nodeId">编辑</el-button><el-button text :disabled="index===0" @click="moveBinding(index,-1)">↑</el-button><el-button text :disabled="index===binding.sources.length-1" @click="moveBinding(index,1)">↓</el-button><el-button text type="danger" @click="removeBinding(index)">移除</el-button></div>
      </div>
      <el-select :model-value="''" filterable placeholder="选择已有节点输出并绑定" @change="bind(outputs.find(o=>outputKey(o)===$event))"><el-option v-for="output in outputs.filter(o=>compatible(o))" :key="outputKey(output)" :label="output.label" :value="outputKey(output)"/></el-select>
      <el-alert v-if="field.kind==='rich'" title="可同时绑定多张图片与文本。生成后按绑定内容组装 JSON 富文本，无需手写 JSON。" type="info" :closable="false"/>
      <el-alert v-if="field.attribute?.dictionaryId" title="仅接受当前类目字典中的选项。AI 文本须精确匹配已有选项，无法匹配时需要人工修正。" type="info" :closable="false"/>
      </template><section v-if="selected" class="node-settings" :class="{'image-settings':mode==='images','direct-material':selected.imageMode==='material'}">
        <div class="section-head"><el-input v-if="!showFields" v-model="selected.label" aria-label="模板名称" placeholder="主图或详情图名称"/><h3 v-else>{{ selected.label }}</h3><el-tag>{{ selected.imageMode==='material'?'资料原图':sourceTypes[currentSource]||WORKFLOW_TYPES[selected.type] }}</el-tag></div>
        <label v-if="showFields">来源类型<el-select :model-value="currentSource" @change="changeSource"><el-option v-for="(label,type) in sourceTypes" :key="type" :label="label" :value="type"/></el-select></label><label v-if="showFields">节点名称<el-input v-model="selected.label" placeholder="例如：俄语标题、主图、材质特写"/></label>
        <template v-if="isWorkflowInput(selected)">
          <label>输入格式<el-select :model-value="selected.type==='images'?'images':selected.inputFormat||'text'" :disabled="Boolean(selected.dictionaryId)" @change="changeFormat"><el-option label="文本" value="text"/><el-option label="数字" value="number"/><el-option label="图片" value="images"/></el-select></label>
          <template v-if="selected.valueSource!=='engineer'"><el-alert title="创建模板时无需填写内容，生产时由用户填写或上传。" type="info" :closable="false"/><label>填写范围<el-select v-model="selected.scope"><el-option label="本次生产共用" value="shared"/><el-option label="每件产品分别填写" value="variant"/></el-select></label><el-checkbox v-model="selected.required">使用流程时必填</el-checkbox></template>
          <template v-if="selected.type==='images'"><label>上传张数<el-input-number v-model="selected.count" :min="1" :max="8" @change="slotsChanged"/></label><label v-for="(_,i) in selected.slots" :key="i">第 {{ i+1 }} 张用途<el-input v-model="selected.slots[i]"/></label><label>图片用途<el-select v-model="selected.referenceRole"><el-option label="产品真实外观" value="product"/><el-option label="视觉参考" value="style"/><el-option label="适配对象参考" value="compatibility"/></el-select></label></template>
          <WorkflowMaterialReferences v-if="selected.type==='images'&&selected.valueSource==='engineer'" v-model="selected.materialRefs" :category="category" direct label="从资料库选用固定图片（也可直接上传）"/><label v-if="selected.valueSource==='engineer'">模板固定内容<WorkflowMaterialInput v-model="selected.defaultValue" :node="selected" :category="category" @options="selected.options=$event" @upload="(file,index)=>emit('upload',file,selected,index)"/></label>
          <WorkflowValuePreview v-if="selected.valueSource==='engineer'" :value="selected.defaultValue" :format="selected.type==='images'?'images':selected.inputFormat||'text'"/><label v-if="selected.valueSource!=='engineer'">填写说明<el-input v-model="selected.help"/></label>
        </template>
        <template v-if="['image','copy'].includes(selected.type)">
          <el-radio-group v-if="selected.type==='image'" :model-value="selected.imageMode||'generate'" @change="selected.imageMode=$event;if($event==='material')selected.materialRefs=(selected.materialRefs||[]).slice(0,1)"><el-radio value="generate">AI 图片生成</el-radio><el-radio value="material">直接使用资料图</el-radio></el-radio-group><div v-if="mode==='images'" class="reference-editors"><el-button v-if="selected.imageMode!=='material'" size="small" @click="addImageReference">添加本节点参考图</el-button><div v-for="entry in referenceEditors" :key="entry.node.id"><div class="reference-title"><strong>{{ selected.role==='main'?'主图风格参考':'本张详情风格参考' }}</strong><el-button link type="danger" @click="removeImageReference(entry.node.id)">移除引用</el-button></div><WorkflowMaterialInput :model-value="entry.indices.map(i=>entry.node.defaultValue?.[i]||'')" :node="referenceNode(entry)" compact :category="category" @update:model-value="updateReference(entry,$event)" @upload="(file,index)=>emit('upload',file,entry.node,entry.indices[index])"/></div><small v-if="selected.role!=='main'&&selected.imageMode!=='material'&&selected.inputs.includes('style')">沿用整套公共风格</small><WorkflowMaterialReferences :category="category" :direct="selected.imageMode==='material'" v-model="selected.materialRefs" :image-references="selected.type==='image'" :label="`本节点生产资料 · ${selected.label}`"/></div>
          <WorkflowMaterialReferences v-if="mode!=='images'" v-model="selected.materialRefs" :image-references="selected.type==='image'" label="本节点生产资料"/><el-collapse v-if="selected.imageMode!=='material'" :model-value="mode==='all'?['node-options']:undefined"><el-collapse-item title="引用材料与输出设置" name="node-options"><label class="input-drop" @dragover.prevent @drop.stop="dropInput($event)">输入材料／引用前序节点（也可拖入）<el-select v-model="selected.inputs" multiple filterable><el-option v-for="node in earlier" :key="node.id" :label="node.label" :value="node.id"/></el-select></label>
          <template v-if="selected.type==='copy'"><label>输出格式<el-select v-model="selected.target"><el-option label="通用文本（任意属性）" value="text"/><el-option label="标题" value="title"/><el-option label="标签列表" value="tags"/><el-option label="简介" value="description"/><el-option label="标题＋标签＋简介" value="bundle"/></el-select></label></template>
          <label v-if="selected.type==='image'">图片比例<el-select v-model="selected.ratio"><el-option v-for="ratio in ['3:4','1:1','4:5']" :key="ratio" :label="ratio" :value="ratio"/></el-select></label>
          <template v-if="selected.type==='image'"><label v-for="source in earlier.filter(n=>n.type==='images'&&n.count>1&&selected.inputs.includes(n.id))" :key="source.id">{{ source.label }} · 本张引用槽位<el-select :model-value="selected.referenceSlots?.[source.id]||[]" multiple placeholder="留空使用全部图片" @change="selected.referenceSlots||={};$event.length?selected.referenceSlots[source.id]=$event:delete selected.referenceSlots[source.id]"><el-option v-for="(slot,index) in source.slots" :key="index" :value="index" :label="slot"/></el-select></label></template>
          </el-collapse-item></el-collapse><el-alert v-if="selected.type==='copy'&&WORKFLOW_COPY_RULES[selected.target]" :title="WORKFLOW_COPY_RULES[selected.target]" type="info" :closable="false"/><label v-if="selected.imageMode!=='material'">生成提示词<el-input v-model="selected.prompt" type="textarea" :rows="mode==='all'?6:mode==='images'?12:8" placeholder="定义这个节点要生成什么，以及必须遵循的规则"/></label>
        </template>
        <template v-if="selected.type==='approval'"><p>兼容已有流程的人工确认节点。</p><el-select v-model="selected.inputs" multiple><el-option v-for="node in earlier.filter(n=>n.type==='image')" :key="node.id" :value="node.id" :label="node.label"/></el-select></template>
        <div class="section-head"><el-button @click="duplicate">复制节点</el-button><el-button plain type="danger" @click="removeNode">删除节点</el-button></div>
      </section>
      <el-empty v-else description="点击左侧添加节点，或选择右侧节点进行编辑"/>
    </main>
    <aside class="builder-panel outputs-panel"><h3>{{ mode==='images'?'主图 / 详情图':mode==='text'?'文案模板':'已有节点与输出' }}</h3><p>{{ showFields?'拖动输出到字段，或点击绑定':'选择一项，编辑参考图与生成规则' }}</p><el-button v-if="!showFields" size="small" @click="create(mode==='images'?'image':'copy')">＋ {{ mode==='images'?'新增图片':'新增文案' }}</el-button><el-empty v-if="!nodes.length" description="先添加一个来源节点"/>
      <article v-for="node in visibleNodes" :key="node.id" class="output-node" :class="{active:selectedId===node.id}"><button class="output-name" @click="selectedId=node.id">{{ node.label }} <small>编辑</small></button><template v-if="showFields"><button v-for="output in workflowNodeOutputs(node)" :key="outputKey(output)" class="output-chip" draggable="true" @dragstart="start($event,{type:'output',output})" @click="bind(output)">{{ output.kind==='image'?'图片':node.inputFormat==='number'?'数字':'文本' }} · {{ output.label }} →</button><p v-if="!workflowNodeOutputs(node).length">辅助节点</p></template></article>
    </aside>
  </div>
